Add-Type -AssemblyName UIAutomationClient; Add-Type -AssemblyName UIAutomationTypes; $root = [System.Windows.Automation.AutomationElement]::RootElement; $condW = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ProcessIdProperty, 17504); $win = $root.FindFirst([System.Windows.Automation.TreeScope]::Children, $condW); $wr = $win.Current.BoundingRectangle; Write-Output ("WIN " + [int]$wr.X + " " + [int]$wr.Y + " " + [int]$wr.Width + " " + [int]$wr.Height); $condE = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::Edit); $edits = $win.FindAll([System.Windows.Automation.TreeScope]::Descendants, $condE); foreach ($e in $edits) { $b = $e.Current.BoundingRectangle; Write-Output ("EDIT " + [int]$b.X + " " + [int]$b.Y + " " + [int]$b.Width + " " + [int]$b.Height) }
